fn in_ranges(character: char, ranges: &[(u32, u32)]) -> bool {
    let codepoint = character as u32;
    ranges
        .binary_search_by(|(start, end)| {
            if codepoint < *start {
                std::cmp::Ordering::Greater
            } else if codepoint > *end {
                std::cmp::Ordering::Less
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .is_ok()
}

pub(crate) fn is_cased(character: char) -> bool {
    in_ranges(character, CASED_RANGES)
}

pub(crate) fn is_case_ignorable(character: char) -> bool {
    in_ranges(character, CASE_IGNORABLE_RANGES)
}

pub(crate) fn lowercase(character: char) -> String {
    mapped(character, LOWERCASE_MAPPINGS)
}

pub(crate) fn titlecase(character: char) -> String {
    mapped(character, TITLECASE_MAPPINGS)
}

fn mapped(character: char, mappings: &[CaseMapping]) -> String {
    let codepoint = character as u32;
    let Ok(index) = mappings.binary_search_by_key(&codepoint, |mapping| mapping.source) else {
        return character.to_string();
    };
    mappings[index].target[..mappings[index].length as usize]
        .iter()
        .filter_map(|value| char::from_u32(*value))
        .collect()
}
